// Native transcription of the owner-supplied May/June 2008, 2009, 2012, 2013 and 2014 source pages.
// Printed questions, figures and choices are retained, including source mistakes.
// These data contain no answer key and do not replace the source provenance record.
const p = (text) => ({ type: "paragraph", text });
const t = (caption, columns, rows) => ({ type: "table", caption, columns, rows });
const q = (number, stem, options, before = []) => ({ number, blocks: [...before, p(stem)], options });
const j = (rows) => ({ blocks: [t("", ["", "Dr $", "Cr $"], rows)] });
const sourceIntro = (text) => p(text);

